import{z as l,x as s,o as A,c as d,q as t,j as o,D as B,d as e,s as r,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"教师激励","description":"","frontmatter":{"title":"教师激励","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ed2-teacher-incentives.md","filePath":"econ/ed2-teacher-incentives.md","lastUpdated":1791413859000}'),c={name:"econ/ed2-teacher-incentives.md"};function p(D,E,h,m,f,u){const n=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="教师激励" tabindex="-1">教师激励 <a class="header-anchor" href="#教师激励" aria-label="Permalink to &quot;教师激励&quot;">​</a></h1><div class="epigraph"><p>工资单按年资和学分定价，产出却按课堂里的增值记账——两张价目表之间的差，就是教师激励的全部空间。</p><footer>—— 据 Lavy, AER 2009；Chetty, Friedman and Rockoff, QJE 2014 整理</footer></div><p><a href="/econ/ed2-production-deep">上一课</a>把课堂质量 \\(q\\) 定位成生产函数里真正起作用的投入，也留下了缺口：\\(q\\) 挂在教师身上，而学校的花名册只记人头、薪级表只认年资。本课把治理问题接过来：给定教师产出的高度异质与难以事前观测，怎么选人、怎么付钱、怎么留人。这是<a href="/econ/moral-hazard">道德风险与隐藏行动</a>在教育现场的具体化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教师劳动市场有三重摩擦叠在一起。第一，产出难以事前观测：增值要等学生数据出来才能估，样本小、噪声大。第二，付酬与产出脱钩：单一薪级表按年资与学分加薪，而上题说过，这些可观测特征几乎解释不了增值——付钱所在的维度不是产出所在的维度。第三，产出多维：分数可测，好奇心、协作、坚持不可测。三重摩擦合起来是双向选择问题：产出高的教师拿不到溢价，会流向付溢价的行业；留下来的构成被薪级表逆向筛选。这不是「教师不敬业」的故事，而是合约结构的故事。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>治理的杠杆有三条。其一，事后筛选：估出每位教师的增值，把分布尾部的低效教师换掉。Hanushek 2011 的推算是：把最末 5%–8% 的教师换成平均教师，美国学生的国际排名能挪到接近头部国家——不新增一分预算，只动分布的尾部。这依赖增值的预测力：Chetty–Friedman–Rockoff 2014 用随机分班的子样本证明，测验口径的教师增值能预测学生成年后的大学入学与收入；按他们的折算，把末位 5% 的教师换成平均教师，一个班级一生收入的现值增加约 25 万美元。<span class="marginnote">数字实例：25 万美元摊到一个班约 25 名学生头上，是每人约 1 万美元的一生收入现值增量——来自一次不加预算的人事替换；账好算，难在解雇与工会那条政治线。</span>其二，事前与事中激励：绩效工资。Lavy 2009 在以色列用锦标赛式奖金——排名达标才拿钱——成绩显著上行，同时改卷伦理出现松动的迹象。<span class="marginnote">术语翻译：锦标赛式奖金就是「按名次发钱，不按绝对水平」——只有排名进入达标线（如前一半）的教师拿奖金。好处是免去设定绝对标准的麻烦（大家都进步时标准会失灵）；坏处是同事从合作者变成了对手。</span>其三，执行最简单的合约：让出勤先被观测。Duflo–Hanna–Ryan 2012 在印度给教室装相机、把工资与出勤挂钩，缺勤率减半，学生成绩随之上升。</p>',7)),(A(),o(i,null,{default:B(()=>[r(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22%E4%BA%A7%E5%87%BA%E9%9A%BE%E4%BA%8B%E5%89%8D%E8%A7%82%E6%B5%8B%22%5D%20--%3E%20L1%5B%22%E4%BA%8B%E5%90%8E%E7%AD%9B%E9%80%89%EF%BC%9A%E5%A2%9E%E5%80%BC%E4%BC%B0%E8%AE%A1%20%2B%20%E6%8D%A2%E5%B0%BE%E9%83%A8%22%5D%0A%20%20M2%5B%22%E4%BB%98%E9%85%AC%E4%B8%8E%E4%BA%A7%E5%87%BA%E8%84%B1%E9%92%A9%22%5D%20--%3E%20L2%5B%22%E7%BB%A9%E6%95%88%E5%B7%A5%E8%B5%84%EF%BC%9A%E9%94%A6%E6%A0%87%E8%B5%9B%E4%B8%8E%E6%8C%87%E6%A0%87%22%5D%0A%20%20M3%5B%22%E4%BA%A7%E5%87%BA%E5%A4%9A%E7%BB%B4%22%5D%20--%3E%20L3%5B%22%E6%89%A7%E8%A1%8C%E5%87%BA%E5%8B%A4%E7%AD%89%E5%8F%AF%E9%AA%8C%E8%AF%81%E5%90%88%E7%BA%A6%22%5D%0A%20%20L1%20--%3E%20Q%5B%22%E8%AF%BE%E5%A0%82%E8%B4%A8%E9%87%8F%20q%22%5D%0A%20%20L2%20--%3E%20Q%0A%20%20L3%20--%3E%20Q%0A%20%20L2%20--%3E%20R%5B%22%E5%A4%9A%E4%BB%BB%E5%8A%A1%E9%A3%8E%E9%99%A9%EF%BC%9A%E5%BA%94%E8%AF%95%E4%B8%8E%E6%94%B9%E5%8D%B7%E6%94%BE%E6%B0%B4%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"教师缺勤是低成本的第一刀：Chaudhury 等 2006 的多国调查显示，发展中国家教师缺勤率普遍落在 10%–25% 区间。缺勤先于质量——人不在教室，增值从何谈起。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("绩效激励的核心难题是多任务：Holmström–Milgrom 1991 的框架说，当一部分任务可测、一部分不可测时，对可测任务付高强度激励，会把努力从不可测任务上系统性抽走——对分数的激励压低对广义技能的供给，这就是 Lavy 结果里改卷松动的那一面。"),a("span",{class:"marginnote"},"常见误区：把多任务问题读成「发奖金没用」。它说的是指标挂错位置时，激励在改写努力的方向而不是数量——Lavy 的成绩上行与改卷松动是同一枚硬币的两面；口径挂对（增值、长期结果），激励仍有空间。"),e("于是激励设计变成了口径设计：指标要尽量挂在长期结果上（增值而非绝对分数），强度要给职业留出不可测任务的空间。")],-1)),E[6]||(E[6]=a("p",null,"努力被可测指标抽走的方向，可以画成两条任务线的分岔。",-1)),(A(),o(i,null,{default:B(()=>[r(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%95%99%E5%B8%88%E7%9A%84%E4%B8%A4%E7%B1%BB%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20A%5B%22%E5%8F%AF%E6%B5%8B%3A%20%E5%BA%94%E8%AF%95%E5%88%86%E6%95%B0%22%5D%0A%20%20T%20--%3E%20B%5B%22%E4%B8%8D%E5%8F%AF%E6%B5%8B%3A%20%E5%A5%BD%E5%A5%87%E5%BF%83%2F%E5%8D%8F%E4%BD%9C%2F%E5%9D%9A%E6%8C%81%22%5D%0A%20%20I%5B%22%E5%AF%B9%E5%88%86%E6%95%B0%E4%BB%98%E9%AB%98%E5%BC%BA%E5%BA%A6%E5%A5%96%E9%87%91%22%5D%20--%3E%20S%5B%22%E5%8A%AA%E5%8A%9B%E4%BB%8E%E4%B8%8D%E5%8F%AF%E6%B5%8B%E4%BE%A7%E6%B5%81%E5%90%91%E5%8F%AF%E6%B5%8B%E4%BE%A7%22%5D%0A%20%20S%20--%3E%20R1%5B%22%E5%88%86%E6%95%B0%E4%B8%8A%E8%A1%8C%22%5D%0A%20%20S%20--%3E%20R2%5B%22%E5%B9%BF%E4%B9%89%E6%8A%80%E8%83%BD%E4%BE%9B%E7%BB%99%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20R1%20--%3E%20D%5B%22%E6%BF%80%E5%8A%B1%E8%AE%BE%E8%AE%A1%20%3D%20%E5%8F%A3%E5%BE%84%E8%AE%BE%E8%AE%A1%3A%20%E6%8C%82%E9%95%BF%E6%9C%9F%E7%BB%93%E6%9E%9C%2C%20%E7%95%99%E4%B8%8D%E5%8F%AF%E6%B5%8B%E7%A9%BA%E9%97%B4%22%5D%0A%20%20R2%20--%3E%20D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p>替代高能激励的是职业关注：<a href="/econ/career-concerns">职业关注</a>的机制在产出噪声大、任期长的学校里依然运转——好业绩换来的是声誉与调任，市场替 principal 部分执行了激励。而尾部筛选的政治成本极高：解雇与裁撤会立即遭遇工会与家长的两面阻力，所以多数体系的实际均衡是「低付酬、低筛选、低进入质量」三件套，单独拉高其中任何一件都不成立。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>增值的估计有分拣问题：学生与教师非随机匹配，只有随机分班的子样本给出干净读数，行政上的增值分数仍是近似。绩效工资的实验多数短期、小样本，规模化后效应衰减。尾部筛选的推算还隐含一个强假设：换掉的岗位能被不低于平均的教师填补——教师供给有弹性约束，这正是劳动市场的问题，不是统计的问题。最后，本课假定学校想提高质量；若学校本身没有竞争压力，教师激励的传导会再断一截——这是下一课的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三重摩擦：产出难测、付酬脱钩、产出多维；后果是逆向筛选而不是敬业问题。</li><li>三条杠杆：尾部筛选（Hanushek 2011）、绩效工资（Lavy 2009）、执行出勤（Duflo–Hanna–Ryan 2012）。</li><li>增值有预测力（Chetty–Friedman–Rockoff 2014），但干净的读数只来自随机分班的子样本。</li><li>多任务问题限制激励强度：对分数的激励会抽走广义技能的努力。</li><li>出处：Rivkin, Hanushek and Kain, Econometrica 2005；Lavy, AER 2009；Chetty, Friedman and Rockoff, QJE 2014；Hanushek, Economics of Education Review 2011；Duflo, Hanna and Ryan, AER 2012。</li></ul>',5))])}const _=l(c,[["render",p]]);export{C as __pageData,_ as default};
